export const BODY: string = "\n<p>کچھ اپ لوڈ فارم سخت ہوتے ہیں۔ وہ 50KB سے نیچے تصویر مانگتے ہیں اور اس سے بڑی ہر چیز کو مسترد کرتے ہیں، چاہے وہ کتنی ہی اچھی لگے۔</p>\n<p>یہ حد جدید فون تصویر کے مقابلے میں چھوٹی لگتی ہے۔ ایک تصویر 4MB یا اس سے زیادہ وزنی ہو سکتی ہے، جو حد سے اسی گنا زیادہ ہے۔</p>\n<p>یہ گائیڈ بتاتی ہے کہ تصویر کو 50KB تک صحیح طریقے سے کیسے کمپریس کریں۔ آپ سیکھیں گے کہ حد کا کیا مطلب ہے، کون سے فارمیٹ اس پر بہترین بچتے ہیں، اور اسے بغیر تصویر خراب کیے کیسے حاصل کریں۔</p>\n<h2 id=\"what-does-50kb-mean\">50KB کا اصل میں کیا مطلب ہے؟</h2>\n<p>کلو بائٹ فائل سائز کی اکائی ہے۔ پچاس کلو بائٹ تقریباً 51,200 بائٹ کے برابر ہوتے ہیں، جدید معیار کے لحاظ سے بہت کم ڈیٹا۔</p>\n<p>موازنے کے لیے، عام فون تصویر 2MB اور 6MB کے درمیان ہوتی ہے۔ اس کا مطلب ہے کہ آپ کو اکثر اصل فائل وزن کا اٹھانوے فیصد سے زیادہ ہٹانا ہوتا ہے۔</p>\n<p>یہ نمبر چھت ہے، ہدف نہیں جس پر بالکل اترنا ہو۔ 49KB فائل پاس ہوتی ہے۔ 51KB فائل ناکام ہوتی ہے، اگرچہ فرق آنکھ کو پوشیدہ ہو۔</p>\n<p>پورٹل نمبر کو بائٹ میں چیک کرتے ہیں، شکل میں نہیں۔ اسی لیے اندازہ کبھی کام نہیں کرتا اور لکیر سے تھوڑا نیچے ہدف رکھنے والا ٹول اہمیت رکھتا ہے۔</p>\n<h2 id=\"why-portals-ask-for-50kb\">پورٹل 50KB کیوں مانگتے ہیں؟</h2>\n<p>سرکاری فارم، امتحان بورڈ، اور جاب پورٹل لاکھوں اپ لوڈ محفوظ کرتے ہیں۔ چھوٹی فائلیں ان کے ڈیٹا بیس کو تیز اور ان کے اسٹوریج بل کو کم رکھتی ہیں۔</p>\n<p>پاسپورٹ پورٹل کو 12 میگا پکسل پورٹریٹ نہیں چاہیے ہوتا۔ اسے صاف چہرہ، درست ابعاد، اور ایسی فائل چاہیے ہوتی ہے جسے اس کا سسٹم ملی سیکنڈ میں پروسیس کر سکے۔</p>\n<p>مقرر حد چیزیں منصفانہ بھی رکھتی ہیں۔ ہر درخواست دہندہ تقریباً ایک ہی وزن اپ لوڈ کرتا ہے، اس لیے کسی کو بھاری فائل سے فائدہ نہیں ملتا۔</p>\n<p>کچھ پرانے سسٹم اس وقت بنے جب بینڈوڈتھ مہنگی تھی۔ ان کی حد کبھی نہیں بدلی، اگرچہ کیمرے بہت بہتر ہو گئے۔</p>\n<h2 id=\"how-compression-reaches-50kb\">کمپریشن 50KB تک کیسے پہنچتی ہے؟</h2>\n<p>کمپریشن وہ ڈیٹا ہٹاتی ہے جسے آنکھ بمشکل دیکھتی ہے۔ یہ معمولی رنگ تبدیلیوں کو ہموار کرتی ہے، باریک شور چھوڑتی ہے، اور مصروف بناوٹ کو آسان کرتی ہے۔</p>\n<p>کوالٹی سیٹنگ کنٹرول کرتی ہے کہ یہ ہٹانا کتنا جارحانہ ہو۔ کم کوالٹی کا مطلب چھوٹی فائل ہے، مگر زیادہ نظر آنے والا نقصان بھی ہے۔</p>\n<p>جب صرف کوالٹی کافی نہ ہو تو ٹول پکسل ابعاد کم کرتا ہے۔ چھوٹی تصویر کو خود کو بیان کرنے کے لیے کم ڈیٹا چاہیے ہوتا ہے۔</p>\n<p>اچھا کمپریسر پہلے مکمل سائز پر کوالٹی آزماتا ہے۔ صرف جب یہ ناکام ہو تو یہ ابعاد کو ایک محتاط قدم سے نیچے لے جاتا ہے۔</p>\n<h2 id=\"binary-quality-search\">بائنری کوالٹی سرچ، آسان الفاظ میں</h2>\n<p>CompressMyPic 50KB ٹول کوالٹی نمبر کا اندازہ نہیں لگاتا۔ یہ بائنری سرچ چلاتا ہے، کوالٹی سطحیں جانچتا ہے جب تک سب سے اعلیٰ سطح نہ ملے جو پھر بھی 50KB سے نیچے فٹ ہو۔</p>\n<p>اسے ایک سے سو کے درمیان نمبر تنگ کرنے کی طرح سوچیں۔ ہر ٹیسٹ باقی حد کو آدھا کر دیتا ہے، اس لیے یہ تیزی سے پہنچتا ہے۔</p>\n<p>یہ اہمیت رکھتا ہے کیونکہ آپ کی تصویر کے لیے بہترین کوالٹی تریسٹھ فیصد ہو سکتی ہے، پچاس یا ستر جیسا گول نمبر نہیں۔ سرچ وہ درست نقطہ تلاش کرتی ہے۔</p>\n<p>نتیجہ آپ کی تصویر کا تیز ترین ممکنہ ورژن ہوتا ہے اس سائز پر جو آپ کو چاہیے، محفوظ مگر بلا ضرورت نرم ورژن کے بجائے۔</p>\n<h2 id=\"best-format-for-50kb\">50KB پر کون سا فارمیٹ بہترین کام کرتا ہے؟</h2>\n<p>لوگوں کی تصاویر کے لیے 50KB پر JPG عام طور پر بہترین انتخاب ہوتا ہے۔ یہ چھوٹے سائز پر ہموار جلد کے رنگ اور گریڈینٹ کو PNG سے کہیں بہتر سنبھالتا ہے۔</p>\n<p>WebP اکثر چھوٹے مارجن سے JPG کو ہراتا ہے۔ یہ اسی فائل وزن پر کناروں کو تھوڑا صاف رکھتا ہے، اگرچہ کچھ پرانے پورٹل اسے قبول نہیں کرتے۔</p>\n<p>PNG اس سائز پر زیادہ تر تصاویر کے لیے غلط انتخاب ہے۔ یہ تصاویر کو بغیر نقصان کے محفوظ کرتا ہے، اس لیے تفصیلی تصویر چھوٹے ابعاد پر بھی 50KB سے کہیں اوپر رہ سکتی ہے۔</p>\n<p>PNG صرف تب استعمال کریں جب آپ کو تیز متن، فلیٹ گرافکس، یا شفافیت چاہیے ہو۔ پورٹریٹ یا اسکین شدہ دستاویز کے لیے JPG یا WebP آپ کی بہتر خدمت کریں گے۔</p>\n<h2 id=\"quality-at-50kb\">50KB پر آپ کس کوالٹی کی توقع کر سکتے ہیں؟</h2>\n<p>اپنے ساتھ ایماندار رہیں: 50KB سمجھوتہ ہے۔ چہرہ پہچاننے کے قابل رہے گا اور دستاویز پڑھنے کے قابل رہے گی، مگر باریک تفصیل نرم ہو جائے گی۔</p>\n<p>پورٹریٹ سب سے بہتر بچتے ہیں کیونکہ چہروں میں ہموار علاقے ہوتے ہیں۔ بال اور کپڑے کچھ بناوٹ کھو دیتے ہیں، پھر بھی مجموعی تصویر صاف لگتی ہے۔</p>\n<p>تفصیلی لینڈ اسکیپ اور مصروف اسکرین شاٹ زیادہ تکلیف اٹھاتے ہیں۔ اسکرین شاٹ میں چھوٹا متن دھندلا ہو سکتا ہے، اس لیے ابعاد کو جتنا حد اجازت دے اتنا بڑا رکھیں۔</p>\n<p>ترکیب یہ ہے کہ ان حصوں کی حفاظت کریں جو اہمیت رکھتے ہیں۔ پاسپورٹ تصویر کو تیز چہرہ چاہیے ہوتا ہے، تیز پس منظر نہیں، اور کمپریشن قدرتی طور پر ہموار علاقوں کو ترجیح دیتی ہے۔</p>\n<h2 id=\"common-uses-for-50kb\">50KB تصویر اصل میں کہاں استعمال ہوتی ہے؟</h2>\n<p>پاسپورٹ اور ویزا درخواستیں کلاسک صورت ہیں۔ بہت سے پورٹل تصویر کو 50KB پر محدود کرتے ہیں اور درست پکسل ابعاد بھی مانگتے ہیں۔</p>\n<p>امتحان رجسٹریشن فارم تصاویر اور دستخطوں کے لیے اسی حد کا استعمال کرتے ہیں۔ اسکین شدہ دستخط زیادہ تر سفید جگہ ہوتا ہے، اس لیے یہ اچھی طرح کمپریس ہوتا ہے۔</p>\n<p>کچھ جاب پورٹل اور یونیورسٹی داخلہ سسٹم پروفائل تصاویر کو 50KB پر محدود کرتے ہیں۔ اس سائز پر صاف ہیڈ شاٹ کسی بھی کنکشن پر فوراً لوڈ ہوتا ہے۔</p>\n<p>اوتار اور فورم پروفائل تصاویر بھی اکثر 50KB کے قریب ہوتی ہیں۔ حد صفحات کو ہلکا رکھتی ہے جب سیکڑوں اوتار ساتھ ظاہر ہوں۔</p>\n<h2 id=\"how-to-use-the-tool\">Compress Image to 50KB ٹول کیسے استعمال کریں</h2>\n<p>اپنے براؤزر میں Compress Image to 50KB ٹول کھولیں۔ سب کچھ آپ کے آلے پر چلتا ہے، اس لیے آپ کی تصویر کبھی سرور پر اپ لوڈ نہیں ہوتی۔</p>\n<p>اپنی تصویر اپ لوڈ علاقے میں ڈال دیں۔ JPG، PNG، WebP، اور HEIC فائلیں قبول کی جاتی ہیں، 25MB تک کے ان پٹ کے ساتھ۔</p>\n<p>ٹول اپنی کوالٹی سرچ خود بخود چلاتا ہے اور آپ کو نتیجہ دکھاتا ہے۔ Under 50KB بیج تلاش کریں، جو تصدیق کرتا ہے کہ فائل حد سے گزر گئی۔</p>\n<p>ڈاؤن لوڈ سے پہلے تصویر کا پیش نظارہ کریں۔ چہرے یا متن پر زوم کریں اور چیک کریں کہ کچھ اہم گڑبڑ نہ ہو گیا ہو۔</p>\n<h2 id=\"mistakes-to-avoid\">غلطیاں جو 50KB کو ضرورت سے مشکل بناتی ہیں</h2>\n<p>سب سے عام غلطی اصل تصویر کے بجائے اسکرین شاٹ سے شروع کرنا ہے۔ اسکرین شاٹ شور بڑھاتے ہیں جو قیمتی کلو بائٹ ضائع کرتا ہے۔</p>\n<p>دوسری غلطی تصویر کے لیے فارمیٹ کو PNG پر لاک کرنا ہے۔ PNG کافی وزن نہیں گرا سکتا، اور ٹول خبردار کرے گا کہ ہدف چھوٹ گیا۔</p>\n<p>لوگ پورٹل اصول چیک کرنا بھی بھول جاتے ہیں۔ اگر پورٹل کو 600 بائی 600 پکسل چاہیے اور WebP مسترد ہو تو کوئی چالاک کمپریشن مدد نہیں کرے گی۔</p>\n<p>آخر میں، پہلے سے کمپریس شدہ فائل کو دوبارہ کمپریس نہ کریں۔ ہر دور نقصان بڑھاتا ہے، اس لیے ہمیشہ اعلیٰ ترین کوالٹی والے اصل سے شروع کریں۔</p>\n<h2 id=\"50kb-vs-other-sizes\">50KB بمقابلہ 100KB بمقابلہ 200KB: فوری موازنہ</h2>\n<p>100KB پر پورٹریٹ 50KB کے مقابلے میں نمایاں زیادہ تفصیل رکھتا ہے۔ بال، چشمے، اور کپڑوں کے کنارے سب صاف لگتے ہیں۔</p>\n<p>200KB پر زیادہ تر تصاویر عام دیکھنے کے سائز پر اصل سے تقریباً ایک جیسی لگتی ہیں۔ اسی لیے بلاگ اور دکانیں اسے ترجیح دیتی ہیں۔</p>\n<p>تبادلہ آسان ہے: چھوٹی فائلیں سخت پورٹل سے گزرتی ہیں، جبکہ بڑی فائلیں بہتر لگتی ہیں۔ سب سے بڑا سائز چنیں جو آپ کا پورٹل اجازت دے۔</p>\n<p>اگر آپ کا پورٹل 100KB قبول کرے تو بغیر وجہ کے 50KB تک نہ نچوڑیں۔ فیصلہ کرنے سے پہلے ہمارا موازنہ <a href=\"/ur/blog/tasveer-size-50kb-vs-100kb-vs-200kb/\">50KB vs 100KB vs 200KB: Which Size to Choose?</a> پڑھیں۔</p>\n<h2 id=\"privacy-and-safety\">پرائیویسی: آپ کی تصویر کا کیا ہوتا ہے؟</h2>\n<p>کمپریشن مکمل طور پر آپ کے براؤزر میں ہوتی ہے۔ آپ کی شناختی تصویر کبھی سرور تک نہیں جاتی، جو اہمیت رکھتا ہے جب فائل پاسپورٹ تصویر ہو۔</p>\n<p>ٹول آپ کی تصویر سے چھپا ہوا مقام ڈیٹا بھی ہٹاتا ہے۔ کمپریشن کے دوران کیمرہ GPS ٹیگ ہٹا دیے جاتے ہیں، اس لیے ڈاؤن لوڈ شدہ فائل میں اس کا کوئی ریکارڈ نہیں ہوتا کہ یہ کہاں لی گئی۔</p>\n<p>یہ شناختی دستاویزات کے لیے حقیقی فائدہ ہے۔ پاسپورٹ تصویر میں آپ کے فون یا گھر کے بارے میں میٹا ڈیٹا نہیں ہونا چاہیے۔</p>\n<p>جمع کرانے سے پہلے ڈاؤن لوڈ شدہ فائل کو ہمیشہ دوبارہ چیک کریں۔ اسے ایک بار کھولیں، تصدیق کریں کہ چہرہ صاف ہے، اور پھر اسے پورٹل پر اپ لوڈ کریں۔</p>\n<h2 id=\"exam-forms-at-50kb\">امتحان اور داخلہ فارم کے لیے 50KB</h2>\n<p>امتحان بورڈ 50KB حد کے سخت ترین استعمال کنندگان میں سے ہیں۔ وہ تصویر اور دستخط دونوں 50KB سے نیچے اور دونوں مقرر فارمیٹ میں مانگتے ہیں۔</p>\n<p>تصویر کے اصول عام طور پر مشکل نصف ہوتے ہیں۔ چہرہ سامنے والا، پس منظر سادہ، اور ابعاد درست ہونے چاہیے، اکثر 200 بائی 230 پکسل یا اس جیسے۔</p>\n<p>دستخط آسان ہوتا ہے۔ دستخط زیادہ تر خالی سفید جگہ ہوتا ہے، اس لیے یہ بغیر کسی نظر آنے والے نقصان کے 50KB سے کہیں نیچے کمپریس ہوتا ہے۔</p>\n<p>فارم کھولنے سے پہلے دونوں فائلیں تیار کریں۔ ڈیڈ لائن دباؤ کے تحت انہیں ایک ایک کر کے اپ لوڈ کرنا غلطیوں کا طریقہ ہے۔</p>\n<p>کمپریس شدہ فائلوں کو exam-photo-50kb.jpg جیسے واضح ناموں سے محفوظ کریں۔ آپ کو یہی فائلیں ایڈمٹ کارڈ یا کونسلنگ راؤنڈ کے لیے دوبارہ چاہیے ہو سکتی ہیں۔</p>\n<h2 id=\"crop-before-compressing\">پہلے کراپ کریں، پھر کمپریس کریں</h2>\n<p>کمپریس کرنے سے پہلے کراپ کرنا 50KB پر سب سے موثر کوالٹی ترکیب ہے۔ ہر پکسل جو آپ ہٹاتے ہیں وہ ڈیٹا ہے جسے کمپریسر کو اب محفوظ نہیں کرنا۔</p>\n<p>خالی آسمان، خالی دیواریں، اور چوڑے مارجن کاٹ دیں۔ موضوع کو فریم میں بڑا اور پس منظر کو کم سے کم رکھیں۔</p>\n<p>پورٹریٹ کے لیے سر اور کندھوں تک کراپ کریں۔ چہرے کو 50KB بجٹ کا زیادہ حصہ ملتا ہے، اس لیے یہ تیز رہتا ہے۔</p>\n<p>اصل فائل پر کراپ کریں، پہلے سے کمپریس شدہ کاپی پر نہیں۔ کمپریشن کے بعد کراپ کرنا کوالٹی دو بار پھینکتا ہے۔</p>\n<p>اگر آپ کا پورٹل مقرر ابعاد مانگے تو پہلے اسی تناسب پر کراپ کریں۔ کمپریشن کے بعد چوڑی تصویر کو 600 بائی 600 کراپ کرنے سے 600 بائی 600 کراپ صاف ہوتا ہے۔</p>\n<h2 id=\"under-50kb-badge\">Under 50KB بیج کو سمجھنا</h2>\n<p>جب ٹول ختم ہو تو یہ کامیاب نتائج پر Under 50KB بیج دکھاتا ہے۔ وہ بیج آپ کی تصدیق ہے کہ فائل پاس ہو گئی۔</p>\n<p>بیج صرف تب ظاہر ہوتا ہے جب حتمی فائل بائٹ میں حد سے نیچے ناپی جائے۔ قریب مگر لکیر سے اوپر والی فائل کو اس کے بجائے وارننگ ملتی ہے۔</p>\n<p>اپنے آلے کی پڑھت پر بیج پر بھروسہ کریں۔ مختلف سسٹم فائل سائز کو مختلف گول کرتے ہیں، اور ٹول درست بائٹ تعداد ناپتا ہے۔</p>\n<p>اگر آپ کو Target missed وارننگ نظر آئے تو ٹول آپ سے ایماندار ہے۔ اس کا مطلب ہے کہ تصویر موجودہ سیٹنگ سے 50KB تک نہیں پہنچ سکی۔</p>\n<p>چھوٹا ہوا ہدف سیٹنگ کا مسئلہ ہے، مردہ انجام نہیں۔ فارمیٹ بدلیں، اسکیلنگ اجازت دیں، یا تنگ کراپ کریں، اور ٹول دوبارہ چلائیں۔</p>\n<h2 id=\"when-50kb-is-impossible\">50KB کب واقعی ناممکن ہوتا ہے</h2>\n<p>کچھ تصاویر بغیر بیکار ہوئے 50KB تک نہیں پہنچ سکتیں۔ بیس چہروں والی گھنی گروپ تصویر ایک مثال ہے۔</p>\n<p>مقرر ابعاد اسے مشکل بناتے ہیں۔ اگر پورٹل بڑا پکسل سائز اور 50KB حد دونوں مانگے تو دونوں اصول ایک دوسرے سے لڑ سکتے ہیں۔</p>\n<p>لاس لیس PNG اسے سب سے مشکل بناتا ہے۔ PNG پر لاک شدہ تفصیلی تصویر کبھی فٹ نہ ہو، چاہے آپ اسے کتنا ہی سکڑیں۔</p>\n<p>ان صورتوں میں وہ بدلیں جو آپ کنٹرول کر سکتے ہیں۔ JPG پر جائیں، تصویر کو تنگ کراپ کریں، یا ابعاد کم کریں اگر پورٹل اجازت دے۔</p>\n<p>اگر کچھ کام نہ کرے تو پورٹل اصول دوبارہ پڑھیں۔ کبھی حد ہر فائل پر نہیں بلکہ مشترکہ اپ لوڈ پر لاگو ہوتی ہے، یا مختلف فارمیٹ قبول ہوتا ہے۔</p>\n<h2 id=\"storing-compressed-files\">کمپریس شدہ فائلیں محفوظ کرنا اور دوبارہ استعمال کرنا</h2>\n<p>اپنی کمپریس شدہ فائلوں کو منظم رکھیں۔ درخواست کے نام والا فولڈر، اندر تصویر اور دستخط کے ساتھ، بعد میں الجھن بچاتا ہے۔</p>\n<p>اصل کو حذف نہ کریں۔ پورٹل اپنے اصول بدلتے ہیں، اور 50KB فائل کو واپس اعلیٰ کوالٹی اصل میں نہیں بدلا جا سکتا۔</p>\n<p>فائلوں کا نام مقصد سے رکھیں، تاریخ سے نہیں۔ visa-photo-50kb.jpg جیسا نام ایک سال بعد مفید ہوتا ہے؛ IMG_4821.jpg جیسا نام نہیں۔</p>\n<p>دوبارہ استعمال سے پہلے محفوظ شدہ فائلیں چیک کریں۔ فائل کو ایک بار کھولیں اور تصدیق کریں کہ یہ پھر بھی درست لگتی ہے اس سے پہلے کہ اسے نئے فارم سے جوڑیں۔</p>\n<p>آخر میں، یاد رکھیں کہ ہر پورٹل مختلف ہوتا ہے۔ ایک امتحان بورڈ کے لیے بنائی گئی فائل دوسرے کے لیے موزوں نہ ہو، اس لیے ہر درخواست کے لیے تازہ کمپریس کریں۔</p>\n<h2 id=\"lighting-and-source-quality\">روشنی اور ماخذ کوالٹی سیٹنگ سے زیادہ اہمیت رکھتی ہیں</h2>\n<p>کوئی کمپریسر خراب ماخذ تصویر کو نہیں بچا سکتا۔ تاریک، شور والی پورٹریٹ 50KB پر پھر بھی تاریک اور شور والی لگے گی، صرف چھوٹی۔</p>\n<p>اچھی روشنی سب سے سستی کوالٹی بہتری ہے۔ کھڑکی کے قریب لی گئی تصویر پیلے بلب کے نیچے لی گئی تصویر کو ہراتی ہے، کسی بھی فائل سائز پر۔</p>\n<p>کیمرہ مستحکم رکھیں اور اسے چہرے پر فوکس کرنے دیں۔ دھندلا اصل دھندلی کاپی میں کمپریس ہوتا ہے، اور کوئی سیٹنگ اسے الٹا نہیں کرتی۔</p>\n<p>پاسپورٹ طرز شاٹ سے پہلے لینس صاف کریں۔ دھندلا لینس دھند بڑھاتا ہے جو چہرے کی تفصیل کے بجائے دھند پر کلو بائٹ ضائع کرتا ہے۔</p>\n<p>جب آپ ماخذ کنٹرول کریں تو فارم کے لیے تازہ تصویر لیں۔ اچھی روشنی سے پانچ منٹ کمپریشن سیٹنگ سے لڑنے کا ایک گھنٹہ بچاتے ہیں۔</p>\n<h2 id=\"backgrounds-and-clothing\">پس منظر، کپڑے، اور کنٹراسٹ</h2>\n<p>سادہ پس منظر مصروف پس منظر سے کہیں بہتر کمپریس ہوتا ہے۔ پس منظر میں ہر پتا، پوسٹر، یا نمونہ کلو بائٹ کھاتا ہے جو چہرہ استعمال کر سکتا تھا۔</p>\n<p>شناختی تصاویر کے لیے ہلکی، خالی دیوار کے سامنے کھڑے ہوں۔ سادہ علاقہ تقریباً کچھ نہیں کمپریس ہوتا، بجٹ چہرے کے لیے چھوڑتا ہے۔</p>\n<p>کپڑے بھی اہمیت رکھتے ہیں۔ باریک چیک نمونے والی قمیض محفوظ کرنا مہنگا ہوتا ہے، جبکہ ٹھوس رنگ تقریباً کچھ نہیں کھاتا۔</p>\n<p>موضوع اور پس منظر کے درمیان کنٹراسٹ کمپریسر کی مدد کرتا ہے۔ ہلکی دیوار کے خلاف تاریک بالوں والا شخص صاف الگ ہوتا ہے، جو کناروں کو تیز رکھتا ہے۔</p>\n<p>یہ چھوٹے انتخاب جمع ہوتے ہیں۔ ساتھ مل کر وہ 50KB پر صاف پاس اور چھوٹے ہوئے ہدف کے درمیان فرق ہو سکتے ہیں۔</p>\n<h2 id=\"retaking-vs-fixing\">دوبارہ کمپریس کرنے کے بجائے کب دوبارہ لیں</h2>\n<p>کبھی کبھی تیز ترین حل نئی تصویر ہوتی ہے، نئی سیٹنگ نہیں۔ اگر ماخذ دھندلا، تاریک، یا بری طرح فریم شدہ ہو تو کمپریشن اسے نہیں بچا سکتی۔</p>\n<p>جب چہرہ فوکس سے باہر ہو تو دوبارہ لیں۔ کوالٹی ٹیوننگ کی کوئی مقدار دھندلی آنکھ کو تیز نہیں کرتی۔</p>\n<p>جب روشنی غلط ہو تو دوبارہ لیں۔ آدھا سائے میں چہرہ خراب کمپریس ہوتا ہے کیونکہ سایہ وہ تفصیل چھپاتا ہے جسے ٹول بحال نہیں کر سکتا۔</p>\n<p>جب فریمنگ جگہ ضائع کرے تو دوبارہ لیں۔ چوڑے شاٹ میں چھوٹا چہرہ کمپریسر کو 50KB پر کام کے لیے تقریباً کچھ نہیں دیتا۔</p>\n<p>دو منٹ کی دوبارہ تصویر بیس منٹ کی ٹویکنگ کو ہراتی ہے۔ اصل کوشش رکھیں، بہتر لیں، اور بہتر کو کمپریس کریں۔</p>\n<p>اگر آپ کو دوسرے فارم کے لیے مختلف حد چاہیے تو <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">100KB compressor</a>، <a href=\"/ur/tasveer-compress-karein-200kb-tak/\">200KB compressor</a>، یا درست اپنی مرضی کے سائز کے لیے <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">target file size compressor</a> آزمائیں۔</p>\n<ul>\n<li>اپنی تصویر 50KB ٹول پر اپ لوڈ کریں۔</li>\n<li>بائنری سرچ کو بہترین کوالٹی تلاش کرنے دیں جو فٹ ہو۔</li>\n<li>نتیجہ کا پیش نظارہ کریں اور چہرے اور متن کو قریب سے چیک کریں۔</li>\n<li>فائل ڈاؤن لوڈ کریں اور اسے اپنے پورٹل پر اپ لوڈ کریں۔</li>\n</ul>\n";

